#include <stdio.h>

/**
 * @brief Calculates the length of a null-terminated string without using strlen().
 *
 * This function iterates through the string character by character,
 * incrementing a counter until the null terminator ('\0') is found.
 *
 * @param str The null-terminated string to measure.
 * @return The length of the string (the number of characters before the null terminator).
 */
size_t custom_strlen(const char *str) {
    if (str == NULL) {
        return 0; // Handle the case where the input pointer is NULL
    }

    size_t length = 0;
    // Loop continues as long as the current character is not the null terminator
    while (str[length] != '\0') {
        length++;
    }

    return length;
}

